// Kiro's balance reflex: step into a push.
// When the pelvis picks up a body-frame velocity that the operator did not command, the reflex
// commands the same velocity (capture-step style), so the policy places a foot under the drift.
import type { ReflexState } from './reflex.js';

export const KIRO_REFLEX = {
  /** Body-frame velocity error below which the command passes through, in m/s. */
  deadband: 0.25,
  /** Command per m/s of velocity error beyond the deadband, in (m/s)/(m/s). */
  gain: 0.8,
  /** Cap on the added lateral command, in m/s. */
  cap: 0.6,
} as const;

export class KiroReflex {
  reset(): void {}

  command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const w = s.qpos[3] as number, x = s.qpos[4] as number, y = s.qpos[5] as number, z = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const vx = s.qvel[0] as number, vy = s.qvel[1] as number;
    const lateral = -sn * vx + c * vy; // m/s, robot frame, + to the robot's left
    const over = Math.abs(lateral) - KIRO_REFLEX.deadband;
    let add = 0;
    if (over > 0 && Number.isFinite(lateral)) {
      add = Math.min(KIRO_REFLEX.cap, KIRO_REFLEX.gain * over) * Math.sign(lateral);
    }
    out[0] = base[0] as number;
    out[1] = (base[1] as number) + add;
    out[2] = base[2] as number;
  }
}

